def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == color and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            minr = min(y for y, x in cells)
            maxr = max(y for y, x in cells)
            minc = min(x for y, x in cells)
            maxc = max(x for y, x in cells)
            shape = {(y - minr, x - minc) for y, x in cells}
            bh, bw = maxr - minr + 1, maxc - minc + 1

            # A component with an enclosed zero in its bounding box moves upward;
            # other components move downward.
            outside = set()
            stack = []
            for y in range(bh):
                for x in range(bw):
                    if (y, x) not in shape and (y in (0, bh - 1) or x in (0, bw - 1)):
                        outside.add((y, x))
                        stack.append((y, x))
            while stack:
                y, x = stack.pop()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < bh and 0 <= nx < bw and
                            (ny, nx) not in shape and (ny, nx) not in outside):
                        outside.add((ny, nx))
                        stack.append((ny, nx))
            enclosed = any((y, x) not in shape and (y, x) not in outside
                           for y in range(bh) for x in range(bw))

            objects.append({
                "color": color, "cells": cells, "shape": shape,
                "top": minr, "left": minc, "height": bh,
                "up": enclosed
            })

    placed = []
    # Closed/enclosing objects settle upward, respecting their original order.
    for obj in sorted((o for o in objects if o["up"]), key=lambda o: o["top"]):
        for top in range(obj["top"] + 1):
            proposed = {(top + y, obj["left"] + x) for y, x in obj["shape"]}
            if not any(proposed & p["cells"] for p in placed):
                placed.append({"cells": proposed, "color": obj["color"]})
                break

    # Remaining objects settle downward.
    for obj in sorted((o for o in objects if not o["up"]),
                      key=lambda o: o["top"], reverse=True):
        for top in range(h - obj["height"], obj["top"] - 1, -1):
            proposed = {(top + y, obj["left"] + x) for y, x in obj["shape"]}
            if not any(proposed & p["cells"] for p in placed):
                placed.append({"cells": proposed, "color": obj["color"]})
                break

    out = [[0] * w for _ in range(h)]
    for obj in placed:
        for y, x in obj["cells"]:
            out[y][x] = obj["color"]
    return out
